package com.huy.enterprise.product; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.RecordStatus; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service @RequiredArgsConstructor public class ProductCategoryService {private final ProductCategoryRepository repo; public List<CategoryResponse> all(){return repo.findAll().stream().map(CategoryResponse::from).toList();}@Transactional public CategoryResponse create(CategoryRequest r){if(repo.existsByCode(r.code()))throw new ConflictException("Category code already exists");return CategoryResponse.from(repo.save(apply(new ProductCategory(),r)));}@Transactional public CategoryResponse update(UUID id,CategoryRequest r){var c=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found: "+id));return CategoryResponse.from(repo.save(apply(c,r)));}private ProductCategory apply(ProductCategory c,CategoryRequest r){c.setName(r.name());c.setCode(r.code());c.setDescription(r.description());c.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());return c;}}
